import { useState, useCallback } from 'react';

export interface Todo {
  id: number;
  text: string;
  completed: boolean;
  createdAt: number;
}

export type Filter = 'all' | 'active' | 'completed';
export type SortOrder = 'newest' | 'oldest' | 'alpha';

export interface TodosState {
  todos: Todo[];
  filter: Filter;
  sort: SortOrder;
  filteredAndSorted: Todo[];
}

export interface TodosActions {
  addTodo: (text: string) => void;
  removeTodo: (id: number) => void;
  toggleTodo: (id: number) => void;
  setFilter: (filter: Filter) => void;
  setSort: (sort: SortOrder) => void;
  clearCompleted: () => void;
}

let nextId = 1;

export function useTodos(): TodosState & TodosActions {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [filter, setFilter] = useState<Filter>('all');
  const [sort, setSort] = useState<SortOrder>('newest');

  // TODO: implement all actions and compute filteredAndSorted
  const filteredAndSorted: Todo[] = [];
  const addTodo = (_text: string) => {};
  const removeTodo = (_id: number) => {};
  const toggleTodo = (_id: number) => {};
  const clearCompleted = () => {};

  return { todos, filter, sort, filteredAndSorted, addTodo, removeTodo, toggleTodo, setFilter, setSort: (s) => setSort(s), clearCompleted };
}

