import { renderHook, act } from '@testing-library/react';
import { useTodos } from './useTodos';

test('starts empty', () => {
  const { result } = renderHook(() => useTodos());
  expect(result.current.todos).toEqual([]);
});

test('addTodo adds a todo', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('Buy milk'));
  expect(result.current.todos).toHaveLength(1);
  expect(result.current.todos[0].text).toBe('Buy milk');
  expect(result.current.todos[0].completed).toBe(false);
});

test('removeTodo removes a todo', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('to remove'));
  const id = result.current.todos[0].id;
  act(() => result.current.removeTodo(id));
  expect(result.current.todos).toHaveLength(0);
});

test('toggleTodo flips completed', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('toggle me'));
  const id = result.current.todos[0].id;
  act(() => result.current.toggleTodo(id));
  expect(result.current.todos[0].completed).toBe(true);
  act(() => result.current.toggleTodo(id));
  expect(result.current.todos[0].completed).toBe(false);
});

test('filter: active shows only incomplete', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('a'));
  act(() => result.current.addTodo('b'));
  act(() => result.current.toggleTodo(result.current.todos[0].id));
  act(() => result.current.setFilter('active'));
  expect(result.current.filteredAndSorted).toHaveLength(1);
  expect(result.current.filteredAndSorted[0].text).toBe('b');
});

test('filter: completed shows only done', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('a'));
  act(() => result.current.addTodo('b'));
  act(() => result.current.toggleTodo(result.current.todos[0].id));
  act(() => result.current.setFilter('completed'));
  expect(result.current.filteredAndSorted).toHaveLength(1);
  expect(result.current.filteredAndSorted[0].text).toBe('a');
});

test('sort: alpha sorts alphabetically', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('Zebra'));
  act(() => result.current.addTodo('Apple'));
  act(() => result.current.setSort('alpha'));
  expect(result.current.filteredAndSorted[0].text).toBe('Apple');
});

test('clearCompleted removes all completed todos', () => {
  const { result } = renderHook(() => useTodos());
  act(() => result.current.addTodo('a'));
  act(() => result.current.addTodo('b'));
  act(() => result.current.toggleTodo(result.current.todos[0].id));
  act(() => result.current.clearCompleted());
  expect(result.current.todos).toHaveLength(1);
  expect(result.current.todos[0].text).toBe('b');
});
